arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_0de1cdd5f60f439eb8683aa8f5efa443.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h1 class="mb-4">Job Application</h1>

    @* ── Step Indicator Bar ── *@
    <nav class="d-flex justify-content-between mb-4 position-relative" aria-label="Application steps">
        @for (int i = 0; i < _stepLabels.Length; i++)
        {
            var step = i + 1;
            var isCompleted = step < _currentStep;
            var isCurrent = step == _currentStep;
            var isFuture = step > _currentStep;

            <button type="button"
                    class="btn p-0 border-0 bg-transparent text-center flex-fill step-indicator"
                    disabled="@(isFuture || _submitted)"
                    @onclick="() => GoToStep(step)"
                    style="cursor: @(isFuture || _submitted ? "default" : "pointer"); opacity: @(isFuture ? "0.4" : "1");">
                <div class="rounded-circle d-inline-flex align-items-center justify-content-center mb-1 @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-secondary text-white")"
                     style="width: 36px; height: 36px; font-size: 0.85rem;">
                    @if (isCompleted)
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </div>
                <div class="small @(isCurrent ? "fw-bold text-primary" : "") @(isFuture ? "text-muted" : "")">
                    @_stepLabels[i]
                </div>
            </button>
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger" role="alert">@_errorMessage</div>
    }

    @if (_submitted)
    {
        @* ── Confirmation ── *@
        <div class="text-center py-5">
            <div class="text-success mb-3" style="font-size: 4rem;">✓</div>
            <h2>Application Submitted!</h2>
            <p class="lead">Your application ID is <strong>#@_applicationId</strong></p>
            <p class="text-muted">We'll be in touch soon. Thank you for applying!</p>
        </div>
    }
    else
    {
        @* ── Step 1: Personal Info ── *@
        @if (_currentStep == 1)
        {
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title mb-3">Personal Information</h4>

                    <div class="mb-3">
                        <label class="form-label">Full Name <span class="text-danger">*</span></label>
                        <input class="form-control" @bind="_fullName" @bind:event="oninput" placeholder="John Doe" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Email <span class="text-danger">*</span></label>
                        <input type="email" class="form-control" @bind="_email" @bind:event="oninput" placeholder="john@example.com" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Phone <span class="text-danger">*</span></label>
                        <input type="tel" class="form-control" @bind="_phone" @bind:event="oninput" placeholder="(555) 123-4567" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Address <span class="text-danger">*</span></label>
                        <textarea class="form-control" rows="2" @bind="_address" @bind:event="oninput" placeholder="123 Main St, City, State"></textarea>
                    </div>

                    <div class="d-flex justify-content-end">
                        <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                            @if (_isValidating) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Next
                        </button>
                    </div>
                </div>
            </div>
        }

        @* ── Step 2: Work History ── *@
        @if (_currentStep == 2)
        {
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title mb-3">Work History</h4>

                    @for (int i = 0; i < _workEntries.Count; i++)
                    {
                        var index = i;
                        var entry = _workEntries[index];

                        <div class="border rounded p-3 mb-3 bg-light">
                            <div class="d-flex justify-content-between align-items-center mb-2">
