@code {
    private static readonly string[] _stepLabels = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep = 1;
    private string? _errorMessage;
    private bool _isValidating;
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;

    // Step 1
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2
    private List<WorkEntryModel> _workEntries = new() { new() };

    // Step 3
    private List<ReferenceModel> _references = new() { new(), new() };

    // Step 4
    private string _coverLetter = string.Empty;

    // Mutable models for form binding
    private record WorkEntryModel
    {
        public string Company { get; init; } = string.Empty;
        public string Title { get; init; } = string.Empty;
        public DateTime StartDate { get; init; } = DateTime.Today;
        public DateTime? EndDate { get; init; }
        public bool IsCurrent { get; init; }
        public string Description { get; init; } = string.Empty;
    }

    private record ReferenceModel
    {
        public string Name { get; init; } = string.Empty;
        public string Relationship { get; init; } = string.Empty;
        public string Email { get; init; } = string.Empty;
        public string Phone { get; init; } = string.Empty;
    }

    private void GoToStep(int step)
    {
        if (step <= _currentStep && !_submitted)
        {
            _currentStep = step;
            _errorMessage = null;
        }
    }

    // Step 1 validation
    private async Task NextFromPersonalInfo()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
            string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            if (!emailValid)
            {
                _errorMessage = "Please enter a valid email address.";
                return;
            }
            _currentStep = 2;
        }
        finally
        {
            _isValidating = false;
        }
    }

    // Step 2
    private void AddWorkEntry() => _workEntries.Add(new());
    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);
    private void UpdateWork(int index, WorkEntryModel entry) => _workEntries[index] = entry;

    private void NextFromWorkHistory()
    {
        _errorMessage = null;

        foreach (var e in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title))
            {
                _errorMessage = "Please fill in the company name and job title for all positions.";
                return;
            }
        }

        _currentStep = 3;
    }

    // Step 3
    private void AddReference()
    {
        if (_references.Count < 3) _references.Add(new());
    }
    private void RemoveReference(int index) => _references.RemoveAt(index);
    private void UpdateRef(int index, ReferenceModel r) => _references[index] = r;

    private void NextFromReferences()
    {
        _errorMessage = null;

        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _errorMessage = "Please fill in all fields for each reference.";
                return;
            }
        }

        _currentStep = 4;
    }

    // Step 4
    private void NextFromCoverLetter()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(_coverLetter))
        {
            _errorMessage = "Please write a cover letter.";
            return;
        }

        _currentStep = 5;
    }

    // Step 5
    private async Task SubmitApplication()
    {
        _errorMessage = null;
        _isSubmitting = true;

        try
        {
            var personal = new PersonalInfo(_fullName.Trim(), _email.Trim(), _phone.Trim(), _address.Trim());
            var workEntries = _workEntries.Select(e =>
                new WorkEntry(e.Company.Trim(), e.Title.Trim(), e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description.Trim())).ToList();
            var work = new WorkHistory(workEntries);
            var refs = _references.Select(r =>
                new Reference(r.Name.Trim(), r.Relationship.Trim(), r.Email.Trim(), r.Phone.Trim())).ToList();

            var application = new JobApplication(personal, work, refs, _coverLetter.Trim());
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

