@page "/apply"
@rendermode InteractiveServer
@using sv_0de1cdd5f60f439eb8683aa8f5efa443.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h1 class="mb-4">Job Application</h1>

    @* ── Step Indicator Bar ── *@
    <nav class="d-flex justify-content-between mb-4 position-relative" aria-label="Application steps">
        @for (int i = 0; i < _stepLabels.Length; i++)
        {
            var step = i + 1;
            var isCompleted = step < _currentStep;
            var isCurrent = step == _currentStep;
            var isFuture = step > _currentStep;

            <button type="button"
                    class="btn p-0 border-0 bg-transparent text-center flex-fill step-indicator"
                    disabled="@(isFuture || _submitted)"
                    @onclick="() => GoToStep(step)"
                    style="cursor: @(isFuture || _submitted ? "default" : "pointer"); opacity: @(isFuture ? "0.4" : "1");">
                <div class="rounded-circle d-inline-flex align-items-center justify-content-center mb-1 @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-secondary text-white")"
                     style="width: 36px; height: 36px; font-size: 0.85rem;">
                    @if (isCompleted)
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </div>
                <div class="small @(isCurrent ? "fw-bold text-primary" : "") @(isFuture ? "text-muted" : "")">
                    @_stepLabels[i]
                </div>
            </button>
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger" role="alert">@_errorMessage</div>
    }

    @if (_submitted)
    {
        @* ── Confirmation ── *@
        <div class="text-center py-5">
            <div class="text-success mb-3" style="font-size: 4rem;">✓</div>
            <h2>Application Submitted!</h2>
            <p class="lead">Your application ID is <strong>#@_applicationId</strong></p>
            <p class="text-muted">We'll be in touch soon. Thank you for applying!</p>
        </div>
    }
    else
    {
        @* ── Step 1: Personal Info ── *@
        @if (_currentStep == 1)
        {
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title mb-3">Personal Information</h4>

                    <div class="mb-3">
                        <label class="form-label">Full Name <span class="text-danger">*</span></label>
                        <input class="form-control" @bind="_fullName" @bind:event="oninput" placeholder="John Doe" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Email <span class="text-danger">*</span></label>
                        <input type="email" class="form-control" @bind="_email" @bind:event="oninput" placeholder="john@example.com" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Phone <span class="text-danger">*</span></label>
                        <input type="tel" class="form-control" @bind="_phone" @bind:event="oninput" placeholder="(555) 123-4567" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Address <span class="text-danger">*</span></label>
                        <textarea class="form-control" rows="2" @bind="_address" @bind:event="oninput" placeholder="123 Main St, City, State"></textarea>
                    </div>

                    <div class="d-flex justify-content-end">
                        <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                            @if (_isValidating) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Next
                        </button>
                    </div>
                </div>
            </div>
        }

        @* ── Step 2: Work History ── *@
        @if (_currentStep == 2)
        {
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title mb-3">Work History</h4>

                    @for (int i = 0; i < _workEntries.Count; i++)
                    {
                        var index = i;
                        var entry = _workEntries[index];

                        <div class="border rounded p-3 mb-3 bg-light">
                            <div class="d-flex justify-content-between align-items-center mb-2">
                                <h6 class="mb-0">Position @(index + 1)</h6>
                                @if (_workEntries.Count > 1)
                                {
                                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                                }
                            </div>

                            <div class="row">
                                <div class="col-md-6 mb-3">
                                    <label class="form-label">Company Name <span class="text-danger">*</span></label>
                                    <input class="form-control" value="@entry.Company"
                                           @onchange="e => UpdateWork(index, entry with { Company = (string?)e.Value ?? string.Empty })" />
                                </div>
                                <div class="col-md-6 mb-3">
                                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                    <input class="form-control" value="@entry.Title"
                                           @onchange="e => UpdateWork(index, entry with { Title = (string?)e.Value ?? string.Empty })" />
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-md-4 mb-3">
                                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                    <input type="date" class="form-control" value="@entry.StartDate.ToString("yyyy-MM-dd")"
                                           @onchange="e => UpdateWork(index, entry with { StartDate = DateTime.Parse((string?)e.Value ?? string.Empty) })" />
                                </div>
                                <div class="col-md-4 mb-3">
                                    <label class="form-label">End Date</label>
                                    <input type="date" class="form-control" disabled="@entry.IsCurrent"
                                           value="@(entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty)"
                                           @onchange="e => UpdateWork(index, entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
                                </div>
                                <div class="col-md-4 mb-3 d-flex align-items-end">
                                    <div class="form-check mb-2">
                                        <input type="checkbox" class="form-check-input" id="current-@index" checked="@entry.IsCurrent"
                                               @onchange="e => UpdateWork(index, entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = (bool)(e.Value ?? false) ? null : entry.EndDate })" />
                                        <label class="form-check-label" for="current-@index">Currently working here</label>
                                    </div>
                                </div>
                            </div>
                            <div class="mb-0">
                                <label class="form-label">Description</label>
                                <textarea class="form-control" rows="2" value="@entry.Description"
                                          @onchange="e => UpdateWork(index, entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
                            </div>
                        </div>
                    }

                    <button class="btn btn-outline-primary btn-sm mb-3" @onclick="AddWorkEntry">
                        + Add Another Position
                    </button>

                    <div class="d-flex justify-content-between">
                        <button class="btn btn-outline-secondary" @onclick="() => GoToStep(1)">Back</button>
                        <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
                    </div>
                </div>
            </div>
        }

        @* ── Step 3: References ── *@
        @if (_currentStep == 3)
        {
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title mb-3">References</h4>

                    @for (int i = 0; i < _references.Count; i++)
                    {
                        var index = i;
                        var r = _references[index];

                        <div class="border rounded p-3 mb-3 bg-light">
                            <div class="d-flex justify-content-between align-items-center mb-2">
                                <h6 class="mb-0">Reference @(index + 1)</h6>
                                @if (_references.Count > 2)
                                {
                                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                                }
                            </div>
                            <div class="row">
                                <div class="col-md-6 mb-3">
                                    <label class="form-label">Name <span class="text-danger">*</span></label>
                                    <input class="form-control" value="@r.Name"
                                           @onchange="e => UpdateRef(index, r with { Name = (string?)e.Value ?? string.Empty })" />
                                </div>
                                <div class="col-md-6 mb-3">
                                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                    <input class="form-control" value="@r.Relationship"
                                           @onchange="e => UpdateRef(index, r with { Relationship = (string?)e.Value ?? string.Empty })" />
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-md-6 mb-3">
                                    <label class="form-label">Email <span class="text-danger">*</span></label>
                                    <input type="email" class="form-control" value="@r.Email"
                                           @onchange="e => UpdateRef(index, r with { Email = (string?)e.Value ?? string.Empty })" />
                                </div>
                                <div class="col-md-6 mb-3">
                                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                                    <input type="tel" class="form-control" value="@r.Phone"
                                           @onchange="e => UpdateRef(index, r with { Phone = (string?)e.Value ?? string.Empty })" />
                                </div>
                            </div>
                        </div>
                    }

                    @if (_references.Count < 3)
                    {
                        <button class="btn btn-outline-primary btn-sm mb-3" @onclick="AddReference">
                            + Add Reference
                        </button>
                    }

                    <div class="d-flex justify-content-between">
                        <button class="btn btn-outline-secondary" @onclick="() => GoToStep(2)">Back</button>
                        <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
                    </div>
                </div>
            </div>
        }

        @* ── Step 4: Cover Letter ── *@
        @if (_currentStep == 4)
        {
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title mb-3">Cover Letter</h4>

                    <div class="mb-2">
                        <textarea class="form-control" rows="10" maxlength="2000"
                                  @bind="_coverLetter" @bind:event="oninput"
                                  placeholder="Tell us why you're a great fit for this position..."></textarea>
                    </div>
                    <div class="text-muted small mb-3 text-end">
                        @(_coverLetter?.Length ?? 0) / 2000 characters
                    </div>

                    <div class="d-flex justify-content-between">
                        <button class="btn btn-outline-secondary" @onclick="() => GoToStep(3)">Back</button>
                        <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
                    </div>
                </div>
            </div>
        }

        @* ── Step 5: Review & Submit ── *@
        @if (_currentStep == 5)
        {
            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="mb-0">Personal Information</h5>
                        <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(1)'>Edit</button>
                    </div>
                    <dl class="row mb-0">
                        <dt class="col-sm-3">Full Name</dt><dd class="col-sm-9">@_fullName</dd>
                        <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                        <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                        <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                    </dl>
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="mb-0">Work History</h5>
                        <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(2)'>Edit</button>
                    </div>
                    @foreach (var entry in _workEntries)
                    {
                        <div class="border-bottom pb-2 mb-2">
                            <strong>@entry.Title</strong> at @entry.Company<br />
                            <span class="text-muted small">
                                @entry.StartDate.ToString("MMM yyyy") –
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                            </span>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mb-0 mt-1 small">@entry.Description</p>
                            }
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="mb-0">References</h5>
                        <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(3)'>Edit</button>
                    </div>
                    @foreach (var r in _references)
                    {
                        <div class="border-bottom pb-2 mb-2">
                            <strong>@r.Name</strong> — @r.Relationship<br />
                            <span class="text-muted small">@r.Email · @r.Phone</span>
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="mb-0">Cover Letter</h5>
                        <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(4)'>Edit</button>
                    </div>
                    <p class="mb-0" style="white-space: pre-wrap;">@_coverLetter</p>
                </div>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-outline-secondary" @onclick="() => GoToStep(4)">Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                    @if (_isSubmitting) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Submit Application
                </button>
            </div>
        }
    }
</div>

@code {
    private static readonly string[] _stepLabels = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

